create table public.order_events (id uuid primary key default gen_random_uuid(), store_id uuid not null, order_id uuid not null, from_status text, to_status text not null, note text, actor_user_id uuid references public.users(id) on delete set null, created_at timestamptz not null default now(), foreign key(store_id,order_id) references public.orders(store_id,id) on delete cascade);
